/**
 * Results explanation panel.
 *
 * Everything shown here is derived from the actual computation: the method
 * name, formula, substituted values and intermediate steps come from the
 * engine's own Explanation object, and the assumptions and limitations are the
 * ones the engine applied. Nothing is generated by a language model, and the
 * panel never invents a causal story from the numbers.
 */
import { EXACTNESS_LABEL, type Explanation } from '../../engine/core/result';
import { Badge, Disclosure } from '../../ui/primitives';

// Headings here sit inside a Card, whose title is an h2, so they are h3:
// skipping a level breaks the document outline for screen readers.

const EXACTNESS_NOTE: Record<Explanation['exactness'], string> = {
  exact: 'This value follows exactly from the inputs by the formula shown. Only floating-point rounding limits its precision.',
  numerical: 'This value is produced by a numerical method (a series, continued fraction or root search) accurate to roughly 10 significant digits or better for the parameters used.',
  empirical: 'This value is an estimate from a finite number of observations or simulated trials. A different sample would give a slightly different answer; the interval shown indicates how much.',
  assumed: 'This value is an assumption you supplied rather than a computed result. The conclusions depend on it being right.',
};

export function ExplanationPanel({ explanation, defaultOpen = false }: { explanation: Explanation; defaultOpen?: boolean }) {
  return (
    <Disclosure title="How this result was calculated" defaultOpen={defaultOpen} icon="book">
      <div className="oc-explanation">
        <div style={{ display: 'flex', gap: 'var(--s2)', flexWrap: 'wrap', marginBottom: 'var(--s3)', alignItems: 'center' }}>
          <Badge variant={explanation.exactness}>{EXACTNESS_LABEL[explanation.exactness]}</Badge>
          <span style={{ fontSize: 12.5, color: 'var(--text-primary)' }}>{explanation.method}</span>
        </div>

        <p style={{ fontSize: 12.5, marginBottom: 'var(--s3)' }}>{EXACTNESS_NOTE[explanation.exactness]}</p>

        {explanation.formula && <div className="oc-explanation__formula">{explanation.formula}</div>}

        {explanation.steps.length > 0 && (
          <>
            <h3 style={{ marginBottom: 'var(--s2)', color: 'var(--text-primary)' }}>Working</h3>
            <ol className="oc-steps">
              {explanation.steps.map((s, i) => (
                <li className="oc-step" key={i}>
                  <span className="oc-step__number" aria-hidden="true" />
                  <div style={{ minWidth: 0 }}>
                    <div className="oc-step__label">{s.label}</div>
                    {s.expression && <div className="oc-step__expression">{s.expression}</div>}
                    {s.value && <div className="oc-step__value">{s.value}</div>}
                  </div>
                </li>
              ))}
            </ol>
          </>
        )}

        {explanation.assumptions.length > 0 && (
          <>
            <h3 style={{ marginBottom: 'var(--s2)', color: 'var(--text-primary)' }}>Assumptions this result depends on</h3>
            <ul className="oc-assumption-list">
              {explanation.assumptions.map((a, i) => (
                <li key={i}>{a}</li>
              ))}
            </ul>
          </>
        )}

        {explanation.limitations.length > 0 && (
          <>
            <h3 style={{ margin: 'var(--s4) 0 var(--s2)', color: 'var(--text-primary)' }}>Limitations</h3>
            <ul className="oc-assumption-list">
              {explanation.limitations.map((a, i) => (
                <li key={i}>{a}</li>
              ))}
            </ul>
          </>
        )}
      </div>
    </Disclosure>
  );
}

/** Assumptions and limitations shown without the step-by-step working. */
export function AssumptionsPanel({ assumptions, limitations, title = 'Assumptions and limitations' }: { assumptions: string[]; limitations?: string[]; title?: string }) {
  if (!assumptions.length && !limitations?.length) return null;
  return (
    <Disclosure title={title} icon="info">
      {assumptions.length > 0 && (
        <>
          <h3 style={{ marginBottom: 'var(--s2)', color: 'var(--text-primary)' }}>Assumptions</h3>
          <ul className="oc-assumption-list">
            {assumptions.map((a, i) => (
              <li key={i}>{a}</li>
            ))}
          </ul>
        </>
      )}
      {limitations && limitations.length > 0 && (
        <>
          <h3 style={{ margin: assumptions.length ? 'var(--s4) 0 var(--s2)' : '0 0 var(--s2)', color: 'var(--text-primary)' }}>Limitations</h3>
          <ul className="oc-assumption-list">
            {limitations.map((a, i) => (
              <li key={i}>{a}</li>
            ))}
          </ul>
        </>
      )}
    </Disclosure>
  );
}
